    ('b8f19418-0617-5b0e-a17f-637eaf38dffb'::uuid, 'Quiz — Par quels yeux le lecteur voit-il l’histoire ?', 'Français', '3e', 'Les différences de focalisation dans un texte', '0a4106b0-bdd3-5164-9bca-5e196100b14b'::uuid),
    ('1247c4e9-6988-5b1e-8d49-03736064359b'::uuid, 'Quiz — Ce qu’un temps verbal fait au sens', 'Français', '3e', 'Les valeurs du présent, du passé simple, de l’imparfait et du futur', 'e4b4522c-8f41-5a14-8c65-78aab461b52e'::uuid),
    ('66050462-5b47-5844-9728-c93e0b296d23'::uuid, 'Quiz — Nommer un procédé, et dire ce qu’il fait', 'Français', '3e', 'Les principales figures de style', 'd1db7b55-136b-5bb0-92cb-f231671a11d7'::uuid),
