    ('81a12911-8560-5176-9728-52cba7d290cf'::uuid, 'Quiz — Les mots pour parler d’un poème', 'Français', '3e', 'Le vocabulaire de la poésie', '76b309f6-1675-5511-8f1a-93b12d36867f'::uuid),
