ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('be5a5e98-e88e-5f81-bb9c-4d96abec6edc'::uuid, 'e8b861c0-da15-5f07-a912-d5f8345b0e25'::uuid, 'Qu’est-ce qu’un autoportrait littéraire ?', 'mcq', '["Une description que l’auteur donne de lui-même","Le récit chronologique de sa vie","Le portrait d’un proche","Un roman à la première personne"]'::jsonb, 0, 'Il décrit un être là où l’autobiographie raconte une vie.', 1),
    ('e17232e9-d1a3-569b-8a36-8d6c4cf48c7b'::uuid, 'e8b861c0-da15-5f07-a912-d5f8345b0e25'::uuid, 'Quelle phrase de Montaigne résume le projet de l’autoportrait ?', 'mcq', '["« Je suis moi-même la matière de mon livre »","« Le moi est haïssable »","« Je pense donc je suis »","« Rien ne sert de courir »"]'::jsonb, 0, 'Elle ouvre les Essais et annonce un livre dont le sujet est son auteur.', 2),
    ('0a6b5c0b-62d2-521c-b445-fb8cb36de7bb'::uuid, 'e8b861c0-da15-5f07-a912-d5f8345b0e25'::uuid, 'Quelle personne grammaticale domine l’autoportrait ?', 'mcq', '["La première personne","La deuxième personne","La troisième personne","La troisième personne du pluriel"]'::jsonb, 0, 'L’auteur parle de lui, en son nom propre.', 3),
    ('fa2e3c18-1b40-5800-a35b-f1c5daa89d79'::uuid, 'e8b861c0-da15-5f07-a912-d5f8345b0e25'::uuid, 'Quel temps donne l’impression d’un être saisi au moment où il écrit ?', 'mcq', '["Le présent d’énonciation","Le passé simple","Le plus-que-parfait","Le futur antérieur"]'::jsonb, 0, 'Il installe l’auteur devant le lecteur, ici et maintenant.', 4),
    ('e9667e6b-03c0-5c56-a27e-168d5d940e93'::uuid, 'e8b861c0-da15-5f07-a912-d5f8345b0e25'::uuid, 'Que distingue-t-on dans un portrait complet ?', 'mcq', '["Le portrait physique et le portrait moral","Le portrait long et le portrait court","Le portrait vrai et le portrait faux","Le portrait en vers et en prose"]'::jsonb, 0, 'Le corps d’un côté, le caractère de l’autre.', 5),
    ('37b14472-55e9-5f9f-869f-5445caec6acc'::uuid, 'e8b861c0-da15-5f07-a912-d5f8345b0e25'::uuid, 'Quel peintre s’est représenté plus de quatre-vingts fois ?', 'mcq', '["Rembrandt","Monet","Delacroix","Picasso"]'::jsonb, 0, 'Ses autoportraits successifs forment une autobiographie peinte.', 6),
    ('0ffbd473-d662-5f59-80ea-e48c45974f64'::uuid, 'e8b861c0-da15-5f07-a912-d5f8345b0e25'::uuid, 'Un autoportrait est-il forcément un miroir fidèle ?', 'mcq', '["Non, c’est une construction : l’auteur choisit ce qu’il montre","Oui, le pacte oblige à tout dire","Oui, sinon ce serait un roman","Non, car il est toujours écrit par un tiers"]'::jsonb, 0, 'Ce que l’auteur veut faire croire de lui fait partie du portrait.', 7),
    ('bdbfebb8-170d-5eba-94a9-95286b83f2e6'::uuid, 'e8b861c0-da15-5f07-a912-d5f8345b0e25'::uuid, 'L’autoportrait suit obligatoirement l’ordre chronologique d’une vie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’autobiographie qui suit le fil du temps ; l’autoportrait décrit.', 8),
    ('82fa6095-fbec-5394-8255-bfdc793410f7'::uuid, '1d3a188b-603b-5d3c-aada-984a35d2f698'::uuid, 'Que signifie littéralement le mot « autobiographie » ?', 'mcq', '["Écrire soi-même sa vie","Écrire la vie d’un autre","Écrire une histoire vraie","Écrire chaque jour"]'::jsonb, 0, 'Du grec auto (soi-même), bios (la vie), graphein (écrire).', 1),
    ('af478392-95c8-5cd3-a8f5-8610c8efe6cb'::uuid, '1d3a188b-603b-5d3c-aada-984a35d2f698'::uuid, 'Qui a formulé la notion de « pacte autobiographique » ?', 'mcq', '["Philippe Lejeune","Jean-Jacques Rousseau","Roland Barthes","Gérard Genette"]'::jsonb, 0, 'Il décrit l’engagement de vérité pris envers le lecteur.', 2),
    ('bfc55339-b2df-59ed-9abe-49aebfc0cd0c'::uuid, '1d3a188b-603b-5d3c-aada-984a35d2f698'::uuid, 'Qu’implique ce pacte ?', 'mcq', '["L’auteur, le narrateur et le personnage principal sont la même personne","Le récit doit être publié après la mort de l’auteur","Le récit doit suivre l’ordre chronologique","Le récit ne doit pas contenir de dialogues"]'::jsonb, 0, 'C’est cette identité triple qui distingue l’autobiographie du roman.', 3),
    ('61419560-f62b-5d14-90b9-f1a34bf54ec7'::uuid, '1d3a188b-603b-5d3c-aada-984a35d2f698'::uuid, 'Que désigne le « regard rétrospectif » ?', 'mcq', '["Le décalage entre l’adulte qui écrit et l’enfant qui a vécu","Le refus de raconter son enfance","Le point de vue d’un témoin extérieur","Le récit écrit au jour le jour"]'::jsonb, 0, 'Deux « je » cohabitent dans le même texte.', 4),
    ('8fa19fbe-2bc9-5dc9-ad73-643d064d6a7b'::uuid, '1d3a188b-603b-5d3c-aada-984a35d2f698'::uuid, 'Quel temps domine pour décrire les habitudes de l’enfance ?', 'mcq', '["L’imparfait","Le passé simple","Le futur simple","Le conditionnel"]'::jsonb, 0, 'Il installe le décor et les gestes répétés.', 5),
    ('669aa435-e64c-5479-881d-4592903c7547'::uuid, '1d3a188b-603b-5d3c-aada-984a35d2f698'::uuid, 'Quel genre s’écrit au jour le jour, sans recul ?', 'mcq', '["Le journal intime","Les Mémoires","L’autofiction","Le roman autobiographique"]'::jsonb, 0, 'Le Journal d’Anne Frank en est l’exemple le plus connu.', 6),
    ('83de5aa9-5a04-53aa-87bd-72a8edb3a9a3'::uuid, '1d3a188b-603b-5d3c-aada-984a35d2f698'::uuid, 'Que racontent surtout les Mémoires ?', 'mcq', '["La vie publique et les grands événements traversés","Les rêves de l’auteur","L’enfance uniquement","La vie d’un proche"]'::jsonb, 0, 'Chateaubriand y traverse la Révolution et l’Empire.', 7),
    ('e239512a-a506-54de-b7e9-ee8bcca0147f'::uuid, '1d3a188b-603b-5d3c-aada-984a35d2f698'::uuid, 'L’autofiction respecte strictement le pacte autobiographique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle mêle volontairement le vécu et l’inventé.', 8),
    ('7095e18b-493b-5533-8bde-7ef8994e06f9'::uuid, '994ea1de-c9fe-5a26-9511-97b2f0c1c182'::uuid, 'Que devient une autobiographie quand l’auteur a traversé un événement historique ?', 'mcq', '["Un témoignage","Un pamphlet","Une fable","Un journal de bord"]'::jsonb, 0, 'L’auteur engage sa parole pour que l’on sache.', 1),
    ('8ac3df16-876f-5abc-9c06-6c9c3edbd5db'::uuid, '994ea1de-c9fe-5a26-9511-97b2f0c1c182'::uuid, 'Quelle œuvre de Primo Levi raconte Auschwitz ?', 'mcq', '["Si c’est un homme","La Peste","Le Journal","Le Premier Homme"]'::jsonb, 0, 'Elle est l’un des grands textes de la littérature concentrationnaire.', 2),
    ('8993ad5b-5b5d-5c8d-8bd1-0d678c4fbd90'::uuid, '994ea1de-c9fe-5a26-9511-97b2f0c1c182'::uuid, 'Quelle double valeur porte un témoignage ?', 'mcq', '["Documentaire et morale","Comique et tragique","Poétique et musicale","Scientifique et technique"]'::jsonb, 0, 'Il informe et il lutte contre l’oubli.', 3),
    ('893b5028-8d2e-58a4-a7b1-620fb4cea3be'::uuid, '994ea1de-c9fe-5a26-9511-97b2f0c1c182'::uuid, 'Dans La Place, que raconte Annie Ernaux à travers son père ?', 'mcq', '["L’écart entre son milieu d’origine et celui où l’école l’a menée","La guerre d’Algérie","Un voyage en Italie","Une histoire d’amour de jeunesse"]'::jsonb, 0, 'Le récit d’une vie éclaire une condition sociale.', 4),
    ('e59055dc-4ea2-5526-901d-8f209e5960f9'::uuid, '994ea1de-c9fe-5a26-9511-97b2f0c1c182'::uuid, 'Pourquoi Annie Ernaux choisit-elle une écriture volontairement plate ?', 'mcq', '["Pour ne pas trahir le monde qu’elle décrit","Parce qu’elle écrit vite","Pour imiter le style de son père","Parce que le sujet est joyeux"]'::jsonb, 0, 'Les effets de style trahiraient la simplicité du milieu raconté.', 5),
    ('e0a8ccdd-aae6-5e1a-90e3-174967d47e90'::uuid, '994ea1de-c9fe-5a26-9511-97b2f0c1c182'::uuid, 'Que raconte Azouz Begag dans Le Gone du Chaâba ?', 'mcq', '["Son enfance dans un bidonville lyonnais","Son service militaire","Une expédition polaire","Sa carrière de peintre"]'::jsonb, 0, 'L’enfance vécue donne à voir l’immigration de l’intérieur.', 6),
    ('85bd9253-7e4c-5d56-81f4-fe2a319cd4cb'::uuid, '994ea1de-c9fe-5a26-9511-97b2f0c1c182'::uuid, 'Qu’est-ce que l’ancrage référentiel ?', 'mcq', '["La présence de dates, de lieux et de noms réels","L’usage exclusif du présent","Le refus de tout dialogue","La présence d’un narrateur extérieur"]'::jsonb, 0, 'Il rattache le récit au monde vérifiable.', 7),
    ('580deebc-5491-58d0-8f70-aef5ea5e42a7'::uuid, '994ea1de-c9fe-5a26-9511-97b2f0c1c182'::uuid, 'Un détail concret vaut souvent mieux qu’une généralité pour faire comprendre une époque.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une odeur, un objet, un mot entendu rendent le passé habitable.', 8),
    ('28d8d252-a361-5c24-891f-a8b624c0ec18'::uuid, 'a4d5c53d-7ba9-555d-9ce6-4ca70b0c8f59'::uuid, 'Quel est le double projet de la satire ?', 'mcq', '["Amuser et corriger","Émouvoir et consoler","Informer et classer","Décrire et raconter"]'::jsonb, 0, 'Elle critique en faisant rire : « castigat ridendo mores ».', 1),
    ('85565957-7493-5c08-abde-d9d449a684a6'::uuid, 'a4d5c53d-7ba9-555d-9ce6-4ca70b0c8f59'::uuid, 'Que fait une caricature ?', 'mcq', '["Elle grossit un trait jusqu’au ridicule","Elle décrit avec exactitude","Elle supprime tout détail","Elle raconte une vie entière"]'::jsonb, 0, 'Le procédé rend le défaut visible d’un seul coup.', 2),
    ('51fa51c6-5e9d-5109-a1bc-5085b5e67ec3'::uuid, 'a4d5c53d-7ba9-555d-9ce6-4ca70b0c8f59'::uuid, 'Quelle différence entre pastiche et parodie ?', 'mcq', '["Le pastiche imite, la parodie imite pour se moquer","Le pastiche est en vers, la parodie en prose","Le pastiche est ancien, la parodie moderne","Il n’y a aucune différence"]'::jsonb, 0, 'La parodie ajoute l’intention moqueuse à l’imitation.', 3),
    ('bdd4b650-ac56-5c2c-ad20-6cba10cef80d'::uuid, 'a4d5c53d-7ba9-555d-9ce6-4ca70b0c8f59'::uuid, 'Qu’est-ce que l’héroï-comique ?', 'mcq', '["Traiter un sujet banal dans un style épique","Traiter un sujet noble dans un style familier","Mélanger vers et prose","Raconter la vie d’un héros réel"]'::jsonb, 0, 'Le burlesque fait exactement l’inverse.', 4),
    ('0f15b8a1-8198-5b9d-b010-fb6aa0bb0fe4'::uuid, 'a4d5c53d-7ba9-555d-9ce6-4ca70b0c8f59'::uuid, 'Quelle figure est au cœur de l’ironie ?', 'mcq', '["L’antiphrase","La métaphore","L’anaphore","La périphrase"]'::jsonb, 0, 'Elle consiste à dire le contraire de ce que l’on pense.', 5),
    ('ce129f96-1ce3-59c2-913e-9070df7d4036'::uuid, 'a4d5c53d-7ba9-555d-9ce6-4ca70b0c8f59'::uuid, 'Pourquoi l’ironie exige-t-elle une complicité avec le lecteur ?', 'mcq', '["Parce que le lecteur doit rétablir seul le vrai sens","Parce qu’elle est toujours écrite en vers","Parce qu’elle s’adresse aux enfants","Parce qu’elle nécessite une note de bas de page"]'::jsonb, 0, 'Sans cette complicité, le texte est compris à l’envers.', 6),
    ('49d472a2-1246-56ae-8e8d-0afa98d37f9a'::uuid, 'a4d5c53d-7ba9-555d-9ce6-4ca70b0c8f59'::uuid, 'À quoi sert l’apologue pour un auteur qui critique le pouvoir ?', 'mcq', '["Il protège : on peut critiquer un roi en parlant d’un lion","Il allonge le récit","Il évite d’avoir à conclure","Il supprime la morale"]'::jsonb, 0, 'Le détour de la fiction déjoue la censure.', 7),
    ('40895ac2-27ec-53e1-8c86-176c75b00c71'::uuid, 'a4d5c53d-7ba9-555d-9ce6-4ca70b0c8f59'::uuid, 'Un pamphlet attaque frontalement, sans passer par le rire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui le distingue de la satire.', 8),
    ('752a8e00-4ff8-53e8-b85d-9c7f1dace96b'::uuid, '6b72698f-0251-53a2-ae31-71c37df67753'::uuid, 'Pourquoi la satire est-elle une arme ?', 'mcq', '["Faire rire d’un puissant lui retire une part de sa puissance","Elle remplace un discours juridique","Elle interdit la publication d’autres textes","Elle est toujours anonyme"]'::jsonb, 0, 'Les pouvoirs la censurent précisément pour cette raison.', 1),
    ('bab07845-a457-5f03-be14-59ffadb63397'::uuid, '6b72698f-0251-53a2-ae31-71c37df67753'::uuid, 'Quelle pièce de Molière contre les faux dévots fut interdite cinq ans ?', 'mcq', '["Tartuffe","Le Misanthrope","L’Avare","Les Fourberies de Scapin"]'::jsonb, 0, 'La cabale des dévots obtint son interdiction.', 2),
    ('9ecc4840-779f-5fd4-8127-6169d185f0cd'::uuid, '6b72698f-0251-53a2-ae31-71c37df67753'::uuid, 'Quel vers ouvre Le Loup et l’Agneau de La Fontaine ?', 'mcq', '["« La raison du plus fort est toujours la meilleure »","« Rien ne sert de courir, il faut partir à point »","« Je plie et ne romps pas »","« Tel est pris qui croyait prendre »"]'::jsonb, 0, 'La morale est annoncée avant même le récit.', 3),
    ('d5f5fa12-c92a-5d1a-bda4-17212bdfa9ac'::uuid, '6b72698f-0251-53a2-ae31-71c37df67753'::uuid, 'Quel est l’intérêt du regard étranger dans la satire ?', 'mcq', '["Il trouve absurde ce que l’habitude a rendu normal","Il permet d’écrire dans une autre langue","Il évite d’avoir à décrire","Il rallonge le texte"]'::jsonb, 0, 'Montesquieu s’en sert dans les Lettres persanes.', 4),
    ('e87ca1c6-413d-558c-b7b3-ad5b31a32963'::uuid, '6b72698f-0251-53a2-ae31-71c37df67753'::uuid, 'Quelle figure feint d’approuver ce que l’on condamne ?', 'mcq', '["L’antiphrase","La comparaison","L’allitération","La litote"]'::jsonb, 0, 'Elle est le cœur de l’ironie.', 5),
    ('2cf8296f-3ad8-5912-855d-3e22d1adbbe7'::uuid, '6b72698f-0251-53a2-ae31-71c37df67753'::uuid, 'Que fait une accumulation dans un texte satirique ?', 'mcq', '["Elle écrase la cible sous une avalanche de détails","Elle suspend le sens","Elle atténue la critique","Elle introduit un dialogue"]'::jsonb, 0, 'La quantité elle-même devient ridicule.', 6),
    ('094a5a1e-6d51-5c98-81ed-3e63a8053a57'::uuid, '6b72698f-0251-53a2-ae31-71c37df67753'::uuid, 'Quelles formes prolongent aujourd’hui la tradition satirique ?', 'mcq', '["Le dessin de presse, la chanson, le sketch","Le manuel scolaire et le dictionnaire","Le mode d’emploi et la notice","Le compte rendu et le procès-verbal"]'::jsonb, 0, 'Le support change, la fonction reste.', 7),
    ('662ea5fa-b600-59d0-9098-f4879dd522f0'::uuid, '6b72698f-0251-53a2-ae31-71c37df67753'::uuid, 'Une satire peut manquer sa cible et blesser ceux qu’elle prétendait défendre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est sa limite : le rire doit viser ce qui mérite d’être combattu.', 8),
    ('df8ea080-bc55-5a2d-af6e-34ca19013dbe'::uuid, '70efd175-e947-5fa3-beea-7628920f3d55'::uuid, 'Que veut dire Rimbaud quand il écrit que le poète « se fait voyant » ?', 'mcq', '["Il perçoit, sous l’apparence, des liens que le regard ordinaire ne voit pas","Il prédit l’avenir avec exactitude","Il décrit uniquement ce qu’il a vu de ses yeux","Il refuse de regarder le monde réel"]'::jsonb, 0, 'Voir devient un travail, pas un don passif.', 1),
    ('0241e8bf-f6b5-5945-b391-bb0b5d96341b'::uuid, '70efd175-e947-5fa3-beea-7628920f3d55'::uuid, 'Qu’appelle-t-on les « correspondances » chez Baudelaire ?', 'mcq', '["Des échos secrets entre parfums, couleurs et sons","Des lettres échangées entre poètes","Des rimes suivies","Des strophes de longueur égale"]'::jsonb, 0, 'Le sonnet Correspondances en fait le programme.', 2),
    ('4bd2032e-dabb-5a66-920a-65e88643e1f0'::uuid, '70efd175-e947-5fa3-beea-7628920f3d55'::uuid, 'Quel recueil de Francis Ponge fait des objets humbles le sujet du poème ?', 'mcq', '["Le Parti pris des choses","Alcools","Les Fleurs du mal","Feuilles d’herbe"]'::jsonb, 0, 'Le pain, l’huître, le cageot y deviennent remarquables.', 3),
    ('19dcf56c-f58f-540d-98c3-836b059a8e77'::uuid, '70efd175-e947-5fa3-beea-7628920f3d55'::uuid, 'Qu’est-ce qu’un enjambement ?', 'mcq', '["La phrase déborde d’un vers sur le suivant","Deux vers riment entre eux","Un vers est répété à l’identique","Un vers compte douze syllabes"]'::jsonb, 0, 'Le décalage entre phrase et vers surprend l’oreille.', 4),
    ('bf8971ab-9513-5854-98bf-14779599bf45'::uuid, '70efd175-e947-5fa3-beea-7628920f3d55'::uuid, 'De quoi est composé un sonnet ?', 'mcq', '["Deux quatrains et deux tercets","Trois quatrains et un distique","Quatre tercets","Deux strophes de six vers"]'::jsonb, 0, 'Quatorze vers au total.', 5),
    ('5d7c3069-0c49-5de8-b778-7de85261d1a6'::uuid, '70efd175-e947-5fa3-beea-7628920f3d55'::uuid, 'Qu’est-ce qu’un calligramme ?', 'mcq', '["Un poème dont la disposition dessine ce dont il parle","Un poème sans rime","Un poème en prose","Un poème de douze vers"]'::jsonb, 0, 'Apollinaire en a fait un recueil entier.', 6),
    ('5177b3c2-0afb-5725-8ed6-3511c57c99e2'::uuid, '70efd175-e947-5fa3-beea-7628920f3d55'::uuid, 'Qu’est-ce que le vers libre ?', 'mcq', '["Un vers sans rime ni mètre régulier","Un vers de onze syllabes","Un vers récité sans ponctuation","Un vers réservé au théâtre"]'::jsonb, 0, 'Le rythme de la phrase y remplace le mètre.', 7),
    ('8aefaf99-93ca-50d1-94da-12bcd5ff2146'::uuid, '70efd175-e947-5fa3-beea-7628920f3d55'::uuid, 'Une forme fixe est toujours plus poétique qu’un vers libre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’usage qu’on en fait qui décide, pas la forme elle-même.', 8),
    ('5a022230-7b50-5d4d-bfa6-dd5ff005be19'::uuid, '8ba257d7-3318-5449-a7c1-fc1f4b9ca46d'::uuid, 'Quelle différence entre comparaison et métaphore ?', 'mcq', '["La comparaison garde un outil comme « comme », la métaphore le supprime","La comparaison est en vers, la métaphore en prose","La comparaison est toujours brève","Il n’y a aucune différence"]'::jsonb, 0, 'La métaphore fait passer une réalité pour une autre, sans transition.', 1),
    ('0d0b864f-319c-59e2-a59e-07706e5b6df1'::uuid, '8ba257d7-3318-5449-a7c1-fc1f4b9ca46d'::uuid, 'Que fait une personnification ?', 'mcq', '["Elle prête des traits humains à une chose ou à un animal","Elle exagère une quantité","Elle répète un mot en tête de vers","Elle inverse l’ordre des mots"]'::jsonb, 0, '« Le vent gémit » en est un exemple.', 2),
    ('bcc0e961-fba9-558d-bc3f-75ad3dfa63f9'::uuid, '8ba257d7-3318-5449-a7c1-fc1f4b9ca46d'::uuid, 'Qu’est-ce qu’une allégorie ?', 'mcq', '["La représentation d’une idée abstraite par une figure concrète","Une comparaison filée sur deux vers","Un poème de quatorze vers","Une répétition de consonnes"]'::jsonb, 0, 'La Mort représentée en faucheuse est l’exemple classique.', 3),
    ('08411781-16c7-5982-adc0-8fbd0c2482e7'::uuid, '8ba257d7-3318-5449-a7c1-fc1f4b9ca46d'::uuid, 'Qu’est-ce qu’une allitération ?', 'mcq', '["La répétition d’une même consonne","La répétition d’une même voyelle","La répétition d’un mot en fin de vers","L’absence de ponctuation"]'::jsonb, 0, 'L’assonance, elle, répète une voyelle.', 4),
    ('34d1bf8a-cbaa-5555-9fef-3920aa4ea206'::uuid, '8ba257d7-3318-5449-a7c1-fc1f4b9ca46d'::uuid, 'Que cherchent les surréalistes dans leurs images ?', 'mcq', '["Rapprocher des mots que rien ne rapprochait, pour étonner","Décrire le réel avec exactitude","Respecter les formes fixes anciennes","Écrire uniquement en alexandrins"]'::jsonb, 0, 'Le rêve et le hasard y deviennent des méthodes.', 5),
    ('dc019dce-7ea7-52de-b110-ec4a5a7c61c4'::uuid, '8ba257d7-3318-5449-a7c1-fc1f4b9ca46d'::uuid, 'Qu’est-ce qu’une anaphore ?', 'mcq', '["La reprise d’un même mot en tête de plusieurs vers","Un vers de dix syllabes","Une rime intérieure","Une strophe de trois vers"]'::jsonb, 0, 'Elle martèle et donne au poème une force d’insistance.', 6),
    ('f9be6b5b-5b40-5c7b-974e-1cc4c4ceb37d'::uuid, '8ba257d7-3318-5449-a7c1-fc1f4b9ca46d'::uuid, 'Quelle question poser devant une image poétique ?', 'mcq', '["Quelles réalités sont rapprochées, et que ce rapprochement fait voir","Combien de syllabes compte le vers","Qui est l’éditeur du recueil","À quelle date le poème a été écrit"]'::jsonb, 0, 'Une métaphore apporte une connaissance, pas un ornement.', 7),
    ('0916a7f4-2b92-5e41-8525-364e4c1b9e23'::uuid, '8ba257d7-3318-5449-a7c1-fc1f4b9ca46d'::uuid, 'Le rythme d’un poème est un simple ornement sans effet sur le sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il porte le sens : un vers court accélère, une anaphore martèle.', 8),
    ('51379d06-9ec7-5297-a439-c63cb3abd669'::uuid, '03c09291-14f5-542a-a782-249535cc733d'::uuid, 'Quel tableau Picasso peint-il après le bombardement d’une ville basque en 1937 ?', 'mcq', '["Guernica","Les Désastres de la guerre","Le Radeau de la Méduse","La Liberté guidant le peuple"]'::jsonb, 0, 'Il devient le symbole mondial de la dénonciation de la guerre.', 1),
    ('68bf28cc-f3df-5ea0-818e-53327b946a70'::uuid, '03c09291-14f5-542a-a782-249535cc733d'::uuid, 'Quelle expression ironique Voltaire emploie-t-il dans Candide pour désigner une bataille ?', 'mcq', '["« boucherie héroïque »","« belle journée »","« art de la guerre »","« champ d’honneur »"]'::jsonb, 0, 'L’adjectif noble accolé au mot boucherie fait toute la charge.', 2),
    ('51282a7f-48be-5672-8673-07570619e8f5'::uuid, '03c09291-14f5-542a-a782-249535cc733d'::uuid, 'Quel roman de Barbusse raconte les tranchées de 1914-1918 ?', 'mcq', '["Le Feu","Le Silence de la mer","Les Misérables","La Peste"]'::jsonb, 0, 'Il paraît en 1916, en pleine guerre.', 3),
    ('6fe9841b-5090-58f2-ac37-18f434a9791d'::uuid, '03c09291-14f5-542a-a782-249535cc733d'::uuid, 'Quel procédé consiste à opposer la beauté du décor à l’horreur des faits ?', 'mcq', '["Le contraste","L’anaphore","La litote","L’ellipse"]'::jsonb, 0, 'Le décalage rend l’horreur plus visible encore.', 4),
    ('21a334d0-a07e-5b4b-962e-cb6c2c5de3c2'::uuid, '03c09291-14f5-542a-a782-249535cc733d'::uuid, 'Quel point de vue les œuvres de dénonciation adoptent-elles le plus souvent ?', 'mcq', '["Celui de la victime ou du simple soldat","Celui de l’état-major","Celui d’un historien du siècle suivant","Celui d’un journaliste neutre"]'::jsonb, 0, 'Regarder d’en bas rend le crime tangible.', 5),
    ('0b1cc174-8a4d-5564-b53d-05b5e45a6ff7'::uuid, '03c09291-14f5-542a-a782-249535cc733d'::uuid, 'Quel registre cherche à provoquer la pitié ?', 'mcq', '["Le registre pathétique","Le registre comique","Le registre didactique","Le registre épique"]'::jsonb, 0, 'Le registre polémique, lui, accuse.', 6),
    ('c46c8245-b046-50eb-9156-4c24ae75fe89'::uuid, '03c09291-14f5-542a-a782-249535cc733d'::uuid, 'Que peut l’art face à la guerre, selon le cours ?', 'mcq', '["Empêcher l’oubli et rendre une voix aux victimes","Arrêter les combats","Remplacer un traité de paix","Juger les responsables"]'::jsonb, 0, 'Il n’arrête pas une guerre, mais il transmet ce que les chiffres ne transmettent pas.', 7),
    ('65e2919b-e4b5-524a-a833-8ee48b3607e0'::uuid, '03c09291-14f5-542a-a782-249535cc733d'::uuid, 'Après la Shoah, certains auteurs ont changé de forme : phrases nues, refus du lyrisme.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La forme choisie devient elle-même une prise de position.', 8),
    ('bd15eb55-d5e3-527f-9973-ff2668333ba3'::uuid, 'b0e17b44-4aa9-5c56-9cbe-818416c54751'::uuid, 'Qu’est-ce qu’un écrivain engagé ?', 'mcq', '["Un auteur qui met son écriture au service d’une cause","Un auteur payé par un journal","Un auteur qui n’écrit que des essais","Un auteur membre d’un parti politique"]'::jsonb, 0, 'Il fait de la littérature un moyen d’agir.', 1),
    ('4838f6fe-c301-5228-876b-f128524c3993'::uuid, 'b0e17b44-4aa9-5c56-9cbe-818416c54751'::uuid, 'Quel texte Zola publie-t-il en 1898 pour défendre le capitaine Dreyfus ?', 'mcq', '["« J’accuse…! »","« Germinal »","« Les Châtiments »","« Le Silence de la mer »"]'::jsonb, 0, 'Publié à la une de L’Aurore, il lui vaut un procès et l’exil.', 2),
    ('66cb4edd-22e5-5d39-a36a-881153f03dbd'::uuid, 'b0e17b44-4aa9-5c56-9cbe-818416c54751'::uuid, 'Contre qui Victor Hugo écrit-il Les Châtiments ?', 'mcq', '["Napoléon III","Louis XVI","Charles X","Napoléon Ier"]'::jsonb, 0, 'Hugo écrit depuis l’exil, après le coup d’État de 1851.', 3),
    ('3afc9d02-b0ef-55a1-b995-1af3b72ae3b0'::uuid, 'b0e17b44-4aa9-5c56-9cbe-818416c54751'::uuid, 'Quel récit Vercors publie-t-il clandestinement sous l’Occupation ?', 'mcq', '["Le Silence de la mer","La Peste","Le Feu","Antigone"]'::jsonb, 0, 'Il paraît en 1942 aux Éditions de Minuit clandestines.', 4),
    ('f5046046-dfe2-527b-b537-8046ab127f6d'::uuid, 'b0e17b44-4aa9-5c56-9cbe-818416c54751'::uuid, 'Quel poète a écrit Liberté, diffusé sous l’Occupation ?', 'mcq', '["Paul Éluard","Arthur Rimbaud","Alfred de Musset","Francis Ponge"]'::jsonb, 0, 'Le poème circule et est parachuté au-dessus de la France occupée.', 5),
    ('e334371b-e6e7-56ad-a539-5d6abee0a1db'::uuid, 'b0e17b44-4aa9-5c56-9cbe-818416c54751'::uuid, 'Quelle figure interpelle directement le destinataire ?', 'mcq', '["L’apostrophe","L’assonance","L’ellipse","L’euphémisme"]'::jsonb, 0, '« Vous qui… » oblige le lecteur à se sentir visé.', 6),
    ('7b98ccbe-8ff2-5d3c-8d3d-2ed63863dc24'::uuid, 'b0e17b44-4aa9-5c56-9cbe-818416c54751'::uuid, 'Quel est l’avantage du détour par la fiction ?', 'mcq', '["Il protège l’auteur et laisse au lecteur le plaisir de comprendre seul","Il permet d’écrire plus vite","Il évite d’avoir un point de vue","Il garantit le succès commercial"]'::jsonb, 0, 'Dire directement frappe fort mais expose à la censure.', 7),
    ('6cd145ca-176f-5b89-ac37-882a70012bfc'::uuid, 'b0e17b44-4aa9-5c56-9cbe-818416c54751'::uuid, 'Aimé Césaire écrit le Cahier d’un retour au pays natal contre le colonialisme.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le texte est l’un des fondements de la négritude.', 8),
    ('db551b6c-3de1-5703-be95-d3e5df32bb07'::uuid, 'b7d2c96e-565e-57e1-a696-03d27d7e9266'::uuid, 'Que désigne l’idée de progrès au XIXe siècle ?', 'mcq', '["L’idée que l’humanité avance grâce au savoir","Le retour aux techniques anciennes","La croissance de la population","L’extension des empires coloniaux"]'::jsonb, 0, 'Elle porte le positivisme et les Expositions universelles.', 1),
    ('823c0937-e366-54b5-a064-2360df567d6a'::uuid, 'b7d2c96e-565e-57e1-a696-03d27d7e9266'::uuid, 'Quel philosophe est associé au positivisme ?', 'mcq', '["Auguste Comte","Jean-Jacques Rousseau","Michel de Montaigne","Blaise Pascal"]'::jsonb, 0, 'Il fonde la confiance de l’époque dans la science.', 2),
    ('dfc12034-3c4f-5e4b-bd47-b773759b4af4'::uuid, 'b7d2c96e-565e-57e1-a696-03d27d7e9266'::uuid, 'Quel genre Jules Verne invente-t-il ?', 'mcq', '["Le roman d’anticipation scientifique","Le roman policier","Le roman épistolaire","La tragédie classique"]'::jsonb, 0, 'Les Voyages extraordinaires en sont la série.', 3),
    ('562ebf40-d5f4-5d45-bcf2-8addafdff3f2'::uuid, 'b7d2c96e-565e-57e1-a696-03d27d7e9266'::uuid, 'Pourquoi les machines de Jules Verne paraissent-elles crédibles ?', 'mcq', '["Parce qu’elles sont décrites avec un sérieux d’ingénieur","Parce qu’elles ont vraiment existé","Parce qu’elles ne sont jamais décrites","Parce qu’elles sont magiques"]'::jsonb, 0, 'Le texte explique le fonctionnement : le lecteur y croit.', 4),
    ('fb6b179e-1bac-5a0f-b8fc-fe23939a3638'::uuid, 'b7d2c96e-565e-57e1-a696-03d27d7e9266'::uuid, 'Quel registre transforme le savant en héros ?', 'mcq', '["Le registre épique","Le registre pathétique","Le registre satirique","Le registre didactique"]'::jsonb, 0, 'La machine y devient un personnage à part entière.', 5),
    ('268adb0f-9ce7-5445-8346-95e3d0cb03a2'::uuid, 'b7d2c96e-565e-57e1-a696-03d27d7e9266'::uuid, 'Qu’est-ce qu’une utopie ?', 'mcq', '["La description d’une société idéale rendue possible par la raison","Un récit de catastrophe","Une autobiographie d’ingénieur","Un poème en vers libres"]'::jsonb, 0, 'Elle critique le présent en montrant ce qu’il pourrait être.', 6),
    ('e669655a-5db9-5fe0-8c3c-c079b5def73b'::uuid, 'b7d2c96e-565e-57e1-a696-03d27d7e9266'::uuid, 'Quel champ lexical domine les textes exaltant le progrès ?', 'mcq', '["La lumière, la conquête, l’élan","L’ombre, la ruine, le froid","La faim, la maladie, la peur","Le silence, l’attente, l’ennui"]'::jsonb, 0, 'Le vocabulaire porte l’enthousiasme.', 7),
    ('6f71c2fd-86e7-5ea5-a2a0-e7fee4f12606'::uuid, 'b7d2c96e-565e-57e1-a696-03d27d7e9266'::uuid, 'L’utopie sert surtout à prédire exactement l’avenir.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle sert d’abord à critiquer le présent.', 8),
    ('5a79b6c3-7bc5-5ad9-b6f4-3e0561458812'::uuid, 'eebd7221-641c-5c9e-b065-4268760d8ea0'::uuid, 'Qui a écrit Frankenstein ou le Prométhée moderne, publié en 1818 ?', 'mcq', '["Mary Shelley","Jules Verne","Bram Stoker","H. G. Wells"]'::jsonb, 0, 'Elle a une vingtaine d’années lorsqu’elle l’écrit.', 1),
    ('d2f0b088-6e8b-5423-bba4-d0aa6043612a'::uuid, 'eebd7221-641c-5c9e-b065-4268760d8ea0'::uuid, 'Pourquoi la créature de Frankenstein devient-elle violente ?', 'mcq', '["Parce qu’elle est rejetée et abandonnée","Parce qu’elle est née mauvaise","Parce qu’elle est mal construite","Parce qu’elle est privée de nourriture"]'::jsonb, 0, 'Le roman déplace la faute du monstre vers son créateur.', 2),
    ('b5bebdec-eb22-5a8d-a24f-7c0ed6a3225d'::uuid, 'eebd7221-641c-5c9e-b065-4268760d8ea0'::uuid, 'À quel personnage mythologique le sous-titre du roman renvoie-t-il ?', 'mcq', '["Prométhée, qui vole le feu aux dieux","Icare, qui vole trop près du soleil","Sisyphe et son rocher","Ulysse et son voyage"]'::jsonb, 0, 'Comme lui, le savant est puni de son audace.', 3),
    ('eb8237df-263e-5b6a-8e3a-25b1eb5ea538'::uuid, 'eebd7221-641c-5c9e-b065-4268760d8ea0'::uuid, 'Qu’est-ce qu’une contre-utopie ?', 'mcq', '["La description d’une société parfaitement organisée mais invivable","Le récit d’une société idéale et heureuse","Une autobiographie de savant","Un poème sur la nature"]'::jsonb, 0, 'On l’appelle aussi dystopie.', 4),
    ('aaf1d55f-f6ac-5857-843c-1d124a369675'::uuid, 'eebd7221-641c-5c9e-b065-4268760d8ea0'::uuid, 'Que supprime la société du Meilleur des mondes pour supprimer la souffrance ?', 'mcq', '["La liberté","La science","La musique","Le langage écrit"]'::jsonb, 0, 'Le bonheur y est fabriqué au prix du choix.', 5),
    ('f6d79e96-4a7f-5c8f-afc3-3dbb994cc140'::uuid, 'eebd7221-641c-5c9e-b065-4268760d8ea0'::uuid, 'Quel roman d’Orwell invente une surveillance totale et une langue appauvrie ?', 'mcq', '["1984","Fahrenheit 451","La Ferme des animaux","Le Meilleur des mondes"]'::jsonb, 0, 'La novlangue y rend la révolte littéralement impensable.', 6),
    ('937330c1-fcc7-5d70-bc07-62ca8f48423c'::uuid, 'eebd7221-641c-5c9e-b065-4268760d8ea0'::uuid, 'Que fait-on des livres dans Fahrenheit 451 de Bradbury ?', 'mcq', '["On les brûle","On les réécrit","On les traduit","On les vend"]'::jsonb, 0, 'Le titre désigne la température d’inflammation du papier.', 7),
    ('efd3dd7a-630c-5b81-aa16-b179ceeb355d'::uuid, 'eebd7221-641c-5c9e-b065-4268760d8ea0'::uuid, 'Ces récits sont des textes hostiles à toute science.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils demandent qui la contrôle, pour quoi et à quel prix.', 8),
    ('d300379a-2fb8-53a2-a812-514592c63472'::uuid, '9b536c3d-30ae-5dd7-8955-1f626207764e'::uuid, 'Quel discours rapporte les paroles telles quelles, entre guillemets ?', 'mcq', '["Le discours direct","Le discours indirect","Le discours indirect libre","Le discours narrativisé"]'::jsonb, 0, 'Un verbe de parole l’introduit ou le suit.', 1),
    ('f7b82eb3-636e-592a-9f79-6ed5b4ec6c73'::uuid, '9b536c3d-30ae-5dd7-8955-1f626207764e'::uuid, 'Comment les paroles sont-elles intégrées au discours indirect ?', 'mcq', '["Dans une subordonnée introduite par « que » ou « si »","Entre guillemets","Après un tiret","En italique sans lien grammatical"]'::jsonb, 0, 'Elles dépendent grammaticalement de la phrase du narrateur.', 2),
    ('9b5040d2-65e9-5b2c-bfff-7a557fb0708f'::uuid, '9b536c3d-30ae-5dd7-8955-1f626207764e'::uuid, 'Au discours indirect, en quoi se transforme un présent ?', 'mcq', '["En imparfait","En passé simple","En futur","Il reste au présent"]'::jsonb, 0, 'La concordance des temps s’applique.', 3),
    ('217e8cb5-7b11-55ab-a86b-cd9774175bad'::uuid, '9b536c3d-30ae-5dd7-8955-1f626207764e'::uuid, 'Que devient « demain » au discours indirect ?', 'mcq', '["« le lendemain »","« aujourd’hui »","« la veille »","« ce jour-là »"]'::jsonb, 0, 'Les repères de temps sont recalculés depuis le récit.', 4),
    ('14d8c8d2-5a25-5ecd-8375-6a14122bf8f4'::uuid, '9b536c3d-30ae-5dd7-8955-1f626207764e'::uuid, 'Quelle est la particularité du discours indirect libre ?', 'mcq', '["Ni guillemets ni « que » : on ne sait plus qui parle","Il emploie toujours le présent","Il exige un verbe de parole","Il est réservé au théâtre"]'::jsonb, 0, 'Flaubert en a fait son outil de prédilection.', 5),
    ('d5565d39-f5ae-52b9-9a05-ecb37d21c3d3'::uuid, '9b536c3d-30ae-5dd7-8955-1f626207764e'::uuid, 'Qu’est-ce que le discours narrativisé ?', 'mcq', '["La parole résumée par un simple verbe, sans être rapportée","La parole rapportée mot à mot","Un dialogue sans ponctuation","Un monologue intérieur"]'::jsonb, 0, '« Il annonça son départ » en est un exemple.', 6),
    ('93b39c05-52b7-5429-9cb7-38b67fea5d0b'::uuid, '9b536c3d-30ae-5dd7-8955-1f626207764e'::uuid, 'Quel effet principal produit le discours direct ?', 'mcq', '["La vivacité : on entend la voix du personnage","La mise à distance","Le résumé rapide","La confusion des voix"]'::jsonb, 0, 'Le lecteur assiste à la scène.', 7),
    ('11ebc933-c156-5633-b95a-fd5372ebe14a'::uuid, '9b536c3d-30ae-5dd7-8955-1f626207764e'::uuid, 'La ponctuation expressive disparaît au passage au discours indirect.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Points d’exclamation et d’interrogation ne survivent pas à la subordination.', 8),
    ('d9bb482d-6a3d-5d21-91ff-25f92235543d'::uuid, 'b8f19418-0617-5b0e-a17f-637eaf38dffb'::uuid, 'Que désigne la focalisation ?', 'mcq', '["La quantité d’information donnée au lecteur et par quels yeux elle passe","Le temps verbal dominant du récit","Le nombre de personnages","La longueur des chapitres"]'::jsonb, 0, 'Elle ne se confond pas avec la personne grammaticale.', 1),
    ('3ed0f6bb-da8a-5435-bd74-426b75774802'::uuid, 'b8f19418-0617-5b0e-a17f-637eaf38dffb'::uuid, 'Quel point de vue permet de connaître les pensées de tous les personnages ?', 'mcq', '["La focalisation zéro","La focalisation interne","La focalisation externe","Le discours indirect libre"]'::jsonb, 0, 'Le narrateur omniscient sait tout, y compris l’avenir.', 2),
    ('4d35139f-c445-5a87-9ba5-32acfc12cea9'::uuid, 'b8f19418-0617-5b0e-a17f-637eaf38dffb'::uuid, 'Quel point de vue crée le plus d’identification et de suspense ?', 'mcq', '["La focalisation interne","La focalisation zéro","La focalisation externe","Le discours narrativisé"]'::jsonb, 0, 'Le lecteur découvre en même temps que le personnage.', 3),
    ('265baec1-f30c-51d0-93db-698b75b5f689'::uuid, 'b8f19418-0617-5b0e-a17f-637eaf38dffb'::uuid, 'Quels indices signalent une focalisation interne ?', 'mcq', '["Les verbes de perception comme « il lui sembla »","Les commentaires du narrateur sur l’avenir","L’absence totale de pensées","La présence de dialogues"]'::jsonb, 0, 'Le doute du personnage devient celui du lecteur.', 4),
    ('73640991-2bd7-5949-8787-67d76206bc8c'::uuid, 'b8f19418-0617-5b0e-a17f-637eaf38dffb'::uuid, 'À quoi compare-t-on souvent la focalisation externe ?', 'mcq', '["À une caméra","À un miroir","À un journal intime","À une lettre"]'::jsonb, 0, 'Elle enregistre gestes et paroles sans entrer dans les consciences.', 5),
    ('5408777e-3aa9-5e85-b4d0-61fc1177d8f2'::uuid, 'b8f19418-0617-5b0e-a17f-637eaf38dffb'::uuid, 'Quel genre utilise volontiers la focalisation interne ?', 'mcq', '["Le fantastique et le policier","Le manuel scolaire","La notice technique","Le dictionnaire"]'::jsonb, 0, 'L’ignorance du personnage fait le suspense.', 6),
    ('21551544-c438-5c95-950c-60508380a96b'::uuid, 'b8f19418-0617-5b0e-a17f-637eaf38dffb'::uuid, 'Que produit l’alternance des points de vue dans un roman ?', 'mcq', '["Le lecteur reconstitue le puzzle à partir de vérités partielles","Le récit devient impossible à suivre","Le narrateur disparaît","Le texte perd sa chronologie"]'::jsonb, 0, 'Une même scène change de sens selon les yeux qui la voient.', 7),
    ('55c11805-363e-58de-acc2-72d4cb32ffa3'::uuid, 'b8f19418-0617-5b0e-a17f-637eaf38dffb'::uuid, 'Un récit à la première personne est forcément en focalisation interne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La personne grammaticale et la focalisation sont deux choses distinctes.', 8),
    ('f9f3fc90-e804-593c-ae06-f7fd6e50d078'::uuid, '1247c4e9-6988-5b1e-8d49-03736064359b'::uuid, 'Quel présent rend une scène de récit plus vivante ?', 'mcq', '["Le présent de narration","Le présent de vérité générale","Le présent d’habitude","Le présent d’énonciation"]'::jsonb, 0, 'Le récit au passé bascule brusquement au présent.', 1),
    ('2defebcc-1ac2-51a1-ab00-15abd719b9c8'::uuid, '1247c4e9-6988-5b1e-8d49-03736064359b'::uuid, 'Quelle valeur a le présent dans « l’eau bout à 100 °C » ?', 'mcq', '["Vérité générale","Énonciation","Habitude","Futur proche"]'::jsonb, 0, 'L’énoncé vaut en tout temps.', 2),
    ('85c3dcba-d9b0-54bc-ae05-a69c2ab63237'::uuid, '1247c4e9-6988-5b1e-8d49-03736064359b'::uuid, 'Que présente le passé simple ?', 'mcq', '["Une action brève et achevée qui fait avancer le récit","Une action en cours et durable","Une action répétée chaque jour","Une action hypothétique"]'::jsonb, 0, 'C’est le temps du premier plan.', 3),
    ('3ce3c150-a0dd-5719-932a-f4178413ff93'::uuid, '1247c4e9-6988-5b1e-8d49-03736064359b'::uuid, 'Quel temps installe le décor et l’arrière-plan du récit ?', 'mcq', '["L’imparfait","Le passé simple","Le passé antérieur","Le futur simple"]'::jsonb, 0, 'Il présente une action en cours, durable ou répétée.', 4),
    ('5882dad0-b4b6-5e27-ba16-51795bab20f8'::uuid, '1247c4e9-6988-5b1e-8d49-03736064359b'::uuid, 'Que décrit un imparfait de rupture ?', 'mcq', '["Une action longue interrompue par un passé simple","Une action instantanée","Une action future","Une action impossible"]'::jsonb, 0, '« Il dormait quand le téléphone sonna. »', 5),
    ('6d618fb9-50f8-57e5-a1d7-fc4868caa7da'::uuid, '1247c4e9-6988-5b1e-8d49-03736064359b'::uuid, 'Qu’exprime le futur antérieur ?', 'mcq', '["Une action achevée avant une autre action à venir","Une action en cours dans le futur","Une action répétée dans le passé","Une hypothèse irréelle"]'::jsonb, 0, '« Quand tu arriveras, j’aurai terminé. »', 6),
    ('b3a20113-3145-597d-9f7c-6fa37d467053'::uuid, '1247c4e9-6988-5b1e-8d49-03736064359b'::uuid, 'Que signale un futur historique dans un récit au passé ?', 'mcq', '["Il annonce une suite que le lecteur ignore encore","Il marque une hypothèse","Il exprime la politesse","Il décrit une habitude"]'::jsonb, 0, '« Cet enfant deviendra empereur. »', 7),
    ('97ed3dca-2792-5e6f-b3a2-ab2d676e78a7'::uuid, '1247c4e9-6988-5b1e-8d49-03736064359b'::uuid, 'Un changement de temps dans un texte est rarement significatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est souvent au moment de la rupture que l’essentiel se produit.', 8),
    ('959818a6-59e0-57f6-a312-4ee0ca61d189'::uuid, '66050462-5b47-5844-9728-c93e0b296d23'::uuid, 'Qu’est-ce qu’un oxymore ?', 'mcq', '["Deux termes contradictoires accolés","Deux termes opposés dans la même phrase","Une exagération","Une répétition en début de vers"]'::jsonb, 0, '« Une obscure clarté » de Corneille en est l’exemple type.', 1),
    ('72e0af04-7824-55ea-aa13-90e823d62199'::uuid, '66050462-5b47-5844-9728-c93e0b296d23'::uuid, 'Qu’est-ce qu’une litote ?', 'mcq', '["Dire moins pour suggérer plus","Exagérer volontairement","Adoucir une réalité pénible","Répéter un mot"]'::jsonb, 0, '« Ce n’est pas mauvais » signifie « c’est excellent ».', 2),
    ('91115e1a-dc63-5c0d-8857-2c4f97b029bc'::uuid, '66050462-5b47-5844-9728-c93e0b296d23'::uuid, 'Quelle figure adoucit une réalité pénible ?', 'mcq', '["L’euphémisme","L’hyperbole","L’anaphore","Le chiasme"]'::jsonb, 0, '« Il nous a quittés » pour « il est mort ».', 3),
    ('66d79b86-62f4-5588-aebe-edc5cc11302e'::uuid, '66050462-5b47-5844-9728-c93e0b296d23'::uuid, 'Qu’est-ce qu’un chiasme ?', 'mcq', '["Une construction croisée de type A-B-B-A","Une répétition en tête de phrase","Une énumération croissante","Une suppression de mot"]'::jsonb, 0, 'Le croisement met les termes en miroir.', 4),
    ('c207d9e4-13b7-5ee2-a35b-c513dc3831a1'::uuid, '66050462-5b47-5844-9728-c93e0b296d23'::uuid, 'Qu’est-ce qu’une gradation ?', 'mcq', '["Une suite de termes de force croissante ou décroissante","Deux structures identiques","Une comparaison sans outil","Une répétition de consonnes"]'::jsonb, 0, 'Elle fait monter ou retomber l’intensité.', 5),
    ('02b5f301-8a0d-5fad-baf9-624e6442f916'::uuid, '66050462-5b47-5844-9728-c93e0b296d23'::uuid, 'Qu’est-ce qu’une métonymie ?', 'mcq', '["Nommer une chose par un lien logique, comme « boire un verre »","Comparer deux réalités avec « comme »","Répéter une voyelle","Supprimer un mot attendu"]'::jsonb, 0, 'Le contenant désigne le contenu.', 6),
    ('931001d1-ddb7-5802-a6c1-8fbecbca7d9b'::uuid, '66050462-5b47-5844-9728-c93e0b296d23'::uuid, 'Qu’est-ce qu’une périphrase ?', 'mcq', '["Dire en plusieurs mots ce qu’un seul suffirait à dire","Employer un mot pour un autre par ironie","Répéter la même structure","Opposer deux termes"]'::jsonb, 0, '« L’astre du jour » pour « le soleil ».', 7),
    ('e9de0586-3359-5429-a5f6-ba2866be8826'::uuid, '66050462-5b47-5844-9728-c93e0b296d23'::uuid, 'Nommer une figure suffit pour répondre à une question de brevet.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut repérer, nommer, puis interpréter l’effet produit.', 8),
    ('bf3bc257-9e0b-554b-90be-da185082d8a0'::uuid, '3d535144-7dd8-5b0d-b21c-bced5858a2d7'::uuid, 'Qu’est-ce que la thèse d’un texte argumentatif ?', 'mcq', '["L’opinion défendue par l’auteur","Le fait précis qui illustre une idée","Le mot de liaison entre deux idées","La conclusion du dernier paragraphe"]'::jsonb, 0, 'Elle peut être annoncée d’emblée ou n’apparaître qu’à la fin.', 1),
    ('612b5806-2ebc-570b-83df-3ea2673c66cf'::uuid, '3d535144-7dd8-5b0d-b21c-bced5858a2d7'::uuid, 'Quelle différence entre un argument et un exemple ?', 'mcq', '["L’argument est une idée, l’exemple est un fait précis","L’argument est court, l’exemple est long","L’argument est écrit, l’exemple est oral","Il n’y a aucune différence"]'::jsonb, 0, 'L’un raisonne, l’autre illustre.', 2),
    ('672e373d-b2cd-5c47-aa41-9c51655e03cc'::uuid, '3d535144-7dd8-5b0d-b21c-bced5858a2d7'::uuid, 'Qu’est-ce qu’une concession ?', 'mcq', '["Reconnaître une part de vérité à la thèse adverse avant de la réfuter","Abandonner sa propre thèse","Répéter l’argument principal","Conclure sans argument"]'::jsonb, 0, 'Elle renforce le texte au lieu de l’affaiblir.', 3),
    ('02c33885-c547-5421-bc89-b85d78cea984'::uuid, '3d535144-7dd8-5b0d-b21c-bced5858a2d7'::uuid, 'Quel connecteur exprime la conséquence ?', 'mcq', '["Par conséquent","Cependant","En effet","Certes"]'::jsonb, 0, '« Donc » et « ainsi » jouent le même rôle.', 4),
    ('0b6b2a45-2825-5572-b7e0-d6fbbcbf016e'::uuid, '3d535144-7dd8-5b0d-b21c-bced5858a2d7'::uuid, 'Quel connecteur introduit une concession ?', 'mcq', '["Certes","Donc","De plus","Enfin"]'::jsonb, 0, 'Il annonce un « mais » à venir.', 5),
    ('c7d37ba3-e8b2-53a1-b41e-631f6d6d4feb'::uuid, '3d535144-7dd8-5b0d-b21c-bced5858a2d7'::uuid, 'Quelle différence entre convaincre et persuader ?', 'mcq', '["Convaincre s’adresse à la raison, persuader aux sentiments","Convaincre est écrit, persuader est oral","Convaincre est long, persuader est bref","Les deux mots sont synonymes"]'::jsonb, 0, 'Les meilleurs textes combinent les deux.', 6),
    ('a8748d1d-d786-5047-9068-490fcd1220b2'::uuid, '3d535144-7dd8-5b0d-b21c-bced5858a2d7'::uuid, 'Qu’est-ce qu’une argumentation indirecte ?', 'mcq', '["Faire comprendre une thèse par une histoire, comme la fable","Écrire une lettre ouverte","Publier un essai","Prononcer un discours"]'::jsonb, 0, 'L’apologue en est la forme la plus classique.', 7),
    ('4f1f1a6e-26c6-59a7-b140-74665fafa7f7'::uuid, '3d535144-7dd8-5b0d-b21c-bced5858a2d7'::uuid, 'Dans un paragraphe argumenté, l’exemple se suffit à lui-même.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sans explication du lien, l’exemple reste décoratif.', 8),
    ('939d4a2a-9fbc-5ccc-9488-dc2be687f962'::uuid, '81a12911-8560-5176-9728-52cba7d290cf'::uuid, 'Combien de syllabes compte un alexandrin ?', 'mcq', '["12","10","8","14"]'::jsonb, 0, 'Le décasyllabe en compte 10, l’octosyllabe 8.', 1),
    ('91af0554-0182-5a8d-b52b-ff9917fa0cc3'::uuid, '81a12911-8560-5176-9728-52cba7d290cf'::uuid, 'Comment s’appelle une strophe de quatre vers ?', 'mcq', '["Un quatrain","Un tercet","Un distique","Un sizain"]'::jsonb, 0, 'Le sonnet en compte deux, suivis de deux tercets.', 2),
    ('74e23f2c-5b58-5f8a-8e2b-a2cd033bd9b4'::uuid, '81a12911-8560-5176-9728-52cba7d290cf'::uuid, 'Quelle est la disposition des rimes croisées ?', 'mcq', '["ABAB","AABB","ABBA","AAAB"]'::jsonb, 0, 'Les rimes plates sont AABB, les embrassées ABBA.', 3),
    ('552bdd5e-b746-505c-aba3-89bf31c3efdc'::uuid, '81a12911-8560-5176-9728-52cba7d290cf'::uuid, 'Qu’est-ce qu’une rime riche ?', 'mcq', '["Une rime qui partage au moins trois sons","Une rime qui partage un seul son","Une rime de fin de strophe","Une rime entre deux vers éloignés"]'::jsonb, 0, 'La rime pauvre n’en partage qu’un, la suffisante deux.', 4),
    ('5a0bd868-16ae-598f-a3af-5c032dcff664'::uuid, '81a12911-8560-5176-9728-52cba7d290cf'::uuid, 'Qu’est-ce qu’un hémistiche ?', 'mcq', '["Chacune des deux moitiés d’un alexandrin séparées par la césure","Une strophe de six vers","Une rime intérieure","Un vers sans rime"]'::jsonb, 0, 'La césure classique tombe après la sixième syllabe.', 5),
    ('e561babb-b0c4-524d-aba5-5272f4b88d83'::uuid, '81a12911-8560-5176-9728-52cba7d290cf'::uuid, 'Qu’est-ce qu’un rejet ?', 'mcq', '["Un mot bref renvoyé au début du vers suivant","Une rime supprimée","Une strophe isolée","Un vers répété"]'::jsonb, 0, 'Le contre-rejet, lui, l’annonce à la fin du vers précédent.', 6),
    ('bd5a797b-a57c-5367-9587-4caf2d3f450b'::uuid, '81a12911-8560-5176-9728-52cba7d290cf'::uuid, 'Qu’est-ce qu’une diérèse ?', 'mcq', '["Prononcer en deux syllabes ce qu’on dit d’ordinaire en une","Supprimer une syllabe","Répéter une voyelle","Couper un vers en deux"]'::jsonb, 0, 'Elle sert souvent à obtenir le compte exact du mètre.', 7),
    ('4b950926-cc17-5465-8941-c0cb71223875'::uuid, '81a12911-8560-5176-9728-52cba7d290cf'::uuid, 'Une rime est dite féminine lorsqu’elle se termine par un e muet.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Toutes les autres sont dites masculines.', 8),
    ('c54f9061-8a85-5ebd-b496-d60708c295f2'::uuid, '2b1b523f-1cd9-5173-9af0-a2aebe25f2ce'::uuid, 'Qu’est-ce qu’une didascalie ?', 'mcq', '["Une indication scénique qui n’est pas prononcée","Une longue réplique","Un échange rapide de répliques","Une scène finale"]'::jsonb, 0, 'Elle indique décor, gestes, ton ou déplacements.', 1),
    ('e4331afe-c2e4-5385-92f7-0dbe3748d6e8'::uuid, '2b1b523f-1cd9-5173-9af0-a2aebe25f2ce'::uuid, 'Qu’est-ce qu’un aparté ?', 'mcq', '["Une parole entendue du public mais pas des autres personnages","Un monologue de fin d’acte","Une réplique de plus de dix vers","Une indication de décor"]'::jsonb, 0, 'Le spectateur devient complice.', 2),
    ('b2daaf44-45ef-529d-b5c3-c28908b3f0bd'::uuid, '2b1b523f-1cd9-5173-9af0-a2aebe25f2ce'::uuid, 'Qu’est-ce qu’une stichomythie ?', 'mcq', '["Un échange de répliques très brèves","Une réplique longue et ininterrompue","Un discours adressé au public","Une scène sans parole"]'::jsonb, 0, 'Elle accélère le rythme et marque souvent l’affrontement.', 3),
    ('2b6709a4-46ad-51f9-b0b9-422fe18c3dc3'::uuid, '2b1b523f-1cd9-5173-9af0-a2aebe25f2ce'::uuid, 'Qu’appelle-t-on la double énonciation ?', 'mcq', '["Un personnage parle à un autre et au public en même temps","Deux personnages parlent ensemble","Une réplique répétée deux fois","Un texte joué deux soirs de suite"]'::jsonb, 0, 'Elle explique les informations rappelées pour le seul spectateur.', 4),
    ('be53e979-c93e-5050-8486-78cfee6f7b6e'::uuid, '2b1b523f-1cd9-5173-9af0-a2aebe25f2ce'::uuid, 'Que posent les scènes d’exposition ?', 'mcq', '["Le lieu, les personnages et l’intrigue","Le dénouement","La morale de la pièce","La liste des accessoires"]'::jsonb, 0, 'Elles donnent au spectateur ce qu’il doit savoir pour suivre.', 5),
    ('64659da2-f7e4-516a-a2c4-5fc46b6e5b30'::uuid, '2b1b523f-1cd9-5173-9af0-a2aebe25f2ce'::uuid, 'Quelles sont les trois unités de la tragédie classique ?', 'mcq', '["Action, lieu, temps","Acte, scène, tableau","Décor, costume, lumière","Auteur, acteur, public"]'::jsonb, 0, 'Le drame romantique les rejette explicitement.', 6),
    ('6bb71e44-7e5e-5e9d-8ea2-593a7aa6d9f2'::uuid, '2b1b523f-1cd9-5173-9af0-a2aebe25f2ce'::uuid, 'Qu’est-ce qu’un quiproquo ?', 'mcq', '["Un malentendu qui fait prendre une chose ou une personne pour une autre","Une répétition de mots","Une chute sur scène","Un défaut poussé à l’extrême"]'::jsonb, 0, 'C’est un ressort du comique de situation.', 7),
    ('46403d7e-c4b6-52af-813a-d11a51122531'::uuid, '2b1b523f-1cd9-5173-9af0-a2aebe25f2ce'::uuid, 'L’ironie tragique naît quand le spectateur sait ce que le personnage ignore.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le décalage de savoir crée la tension.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('francais');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('francais')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 290 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 290 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
